def execute(self, ident, now, crash=False):
    with self.db:
        self.db.execute('BEGIN IMMEDIATE')
        row = self.db.execute('SELECT revision,bill,principal,discount,'
            'expires,received,executed FROM quotes WHERE id=?',
            (ident,)).fetchone()
        if not row:
            raise ValueError('unknown quote')
        revision, bill, principal, discount, expires, received, done = row
        needed = bill + principal - discount
        if done:
            return dict(applied=needed, unapplied=received - needed)
        current = self.db.execute('SELECT revision FROM contract').fetchone()[0]
        if now >= expires or revision != current:
            raise ValueError('expired or stale quote; funds remain unapplied')
        if received < needed:
            raise ValueError('full quoted amount not received')
        self.db.execute('UPDATE contract SET revision=revision+1,'
                        'settled=settled+?', (principal,))
        self.db.execute('UPDATE quotes SET executed=1 WHERE id=?', (ident,))
        if crash:
            raise RuntimeError('crash before commit')
    return dict(applied=needed, unapplied=received - needed)

def withdraw(self, actor, key, cents, snapshot, now, ledger_online=True):
    with self.lock:
        for value in (actor, key, snapshot.owner):
            identifier(value)
        if type(now) is not int or now < 0:
            raise ValueError('invalid clock')
        if actor != self.owner or snapshot.owner != actor:
            raise PermissionError('account scope')
        if not key or type(cents) is not int or cents <= 0:
            raise ValueError('invalid command')
        command = (actor, cents)
        if key in self.receipts:
            prior_command, receipt = self.receipts[key]
            if prior_command != command:
                raise ValueError('idempotency conflict')
            return receipt
        if not ledger_online:
            raise RuntimeError('authority unavailable')
        if not 0 <= now - snapshot.observed_at <= 30:
            raise ValueError('snapshot expired')
        if snapshot.version != self.version:
            raise ValueError('refresh required')
        if cents > self.balance:
            raise ValueError('insufficient funds')
        self.balance -= cents
        self.version += 1
        receipt = (key, cents, self.version)
        self.receipts[key] = (command, receipt)
        return receipt

